package com.rgds.ultimate.shell;
/** Full shipped font cmap; decoded only when diagnostics request coverage. */
final class PixelCoverage {
 private static final String DATA="";
 private static byte[] bits;
 private static synchronized byte[] data(){if(bits==null)bits=android.util.Base64.decode(DATA,android.util.Base64.DEFAULT);return bits;}
 static boolean contains(int cp){byte[] map=data();return cp>=0&&cp/8<map.length&&(map[cp/8]&(1<<(cp%8)))!=0;}
 static org.json.JSONArray missing(CharSequence value){java.util.LinkedHashSet<Integer> missing=new java.util.LinkedHashSet<>();for(int n=0;n<value.length();){int cp=Character.codePointAt(value,n);n+=Character.charCount(cp);if(!Character.isWhitespace(cp)&&!contains(cp))missing.add(cp);}org.json.JSONArray out=new org.json.JSONArray();for(int cp:missing)out.put("U+"+Integer.toHexString(cp).toUpperCase(java.util.Locale.ROOT));return out;}
}
